head.script:
scwin.gridView2_col1_checkboxLabelFormatter = function(row, col, label) {
    return "[" + row + "," + col + "]";
}
scwin.gridView2_col2_radioLabelFormatter = function(row, col, label) {
    return label + ":(" + row + "," + col + ")";
}
scwin.gridView3_col1_checkboxLabelFormatter = function(row, col, label) {
    return "[" + row + "," + col + "]";
}
scwin.gridView3_col2_radioLabelFormatter = function(row, col, label) {
    return "(" + row + "," + col + ")";
}
scwin.checkVal1 = function() {
    return gridView3.getAttribute('focusMove') == true;
}
scwin.checkVal2 = function() {
    return gridView3.getAttribute('senseReader') == true;
}
scwin.checkVal3 = function() {
    return gridView3.getAttribute('keyMoveEditMode') == true;
}
scwin.getAttr = function(id, attr) {
    var dataAttr = WebSquare.util.getDataPrefix(attr);
    return WebSquare.wUnit.getDomById($p.id + id).getAttribute(dataAttr);
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. Script 탭을 확인한다.
    //1. Check the Script tab.
    //Verify step 1. 코멘트참고
    //1. Comment Reference
    //Test step 2. Source 탭에서 gridView2 의 col1 의 checkboxLabelFormatter 부분을 확인한다.
    //2. In the Source tab, check the checkboxLabelFormatter part of col1 in gridView2.
    //WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 2. checkboxLabelFormatter='scwin.gridView2_col1_checkboxLabelFormatter'
    //2. checkboxLabelFormatter = 'scwin.gridView2_col1_checkboxLabelFormatter'
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView2_cell_0_1').getAttribute('checkboxLabelFormatter')", "scwin.gridView2_col1_checkboxLabelFormatter");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView2_cell_1_1').getAttribute('checkboxLabelFormatter')", "scwin.gridView2_col1_checkboxLabelFormatter");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView2_cell_2_1').getAttribute('checkboxLabelFormatter')", "scwin.gridView2_col1_checkboxLabelFormatter");
    //Test step 3. col2 의 radioLabelFormatter 부분을 확인한다.
    //3. Check the radioLabelFormatter part of col2.
    //WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 3. radioLabelFormatter='scwin.gridView2_col2_radioLabelFormatter'
    //3. radioLabelFormatter = 'scwin.gridView2_col2_radioLabelFormatter'
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView2_cell_0_2').getAttribute('radioLabelFormatter')", "scwin.gridView2_col2_radioLabelFormatter");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView2_cell_1_2').getAttribute('radioLabelFormatter')", "scwin.gridView2_col2_radioLabelFormatter");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView2_cell_2_2').getAttribute('radioLabelFormatter')", "scwin.gridView2_col2_radioLabelFormatter");
    //Test step 4. gridView3 의 col1 의 checkboxLabelFormatter 부분을 확인한다.
    //4. Check the checkboxLabelFormatter part of col1 in gridView3.
    //WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 4. checkboxLabelFormatter='scwin.gridView3_col1_checkboxLabelFormatter'
    //4. checkboxLabelFormatter = 'scwin.gridView3_col1_checkboxLabelFormatter'
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView3_cell_0_1').getAttribute('checkboxLabelFormatter')", "scwin.gridView3_col1_checkboxLabelFormatter");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView3_cell_1_1').getAttribute('checkboxLabelFormatter')", "scwin.gridView3_col1_checkboxLabelFormatter");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView3_cell_2_1').getAttribute('checkboxLabelFormatter')", "scwin.gridView3_col1_checkboxLabelFormatter");
    //Test step 5. col2 의 radioLabelFormatter 부분을 확인한다.
    //5. Check the radioLabelFormatter part of col2.
    //WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 5. radioLabelFormatter='scwin.gridView3_col2_radioLabelFormatter'
    //5. radioLabelFormatter = 'scwin.gridView3_col2_radioLabelFormatter'
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView3_cell_0_2').getAttribute('radioLabelFormatter')", "scwin.gridView3_col2_radioLabelFormatter");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView3_cell_1_2').getAttribute('radioLabelFormatter')", "scwin.gridView3_col2_radioLabelFormatter");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView3_cell_2_2').getAttribute('radioLabelFormatter')", "scwin.gridView3_col2_radioLabelFormatter");
    //Test step 6. datalist3 의 focusMove / senseReader / keyMoveEditMode 부분을 확인한다.
    //6. Check the focusMove / senseReader / keyMoveEditMode part of datalist3.
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 6. focusMove='false' senseReader='true' keyMoveEditMode='true'
    //6. focusMove = 'false' senseReader = 'true' keyMoveEditMode = 'true'
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "false");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    //Test step 7. Source 탭 또는 Property 탭에서 gridView1 의 Header : column5 / column3 column6 / column1 // Body : col1 / col2 / col3 / col4 embeddedInput 부분을 확인한다.
    //7. In the Source or Property tab, check the embeddedInput part of the header: column5 / column3 column6 / column1 // body: col1 / col2 / col3 / col4 of gridView1.
    //Verify step 7. embeddedInput='true'
    //7. embeddedInput = 'true'
    //Test step 8. 브라우저에서 label 이 출력된 CheckBox 에 Header 라벨부분을 클릭한다.
    //8. Click on the header label portion of the CheckBox where the label is displayed in the browser.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column6').childNodes[0].click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 8. 전체체크 & 전체체크된다.
    //8. Check all & Check all.
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_7_header__column6_id').checked", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_column6').childNodes[1].checked", "true");
    WebSquare.wUnit.addCommand("assert", "document.getElementsByClassName('w2grid_embedded_check')[1].checked", "true");
    WebSquare.wUnit.addCommand("assert", "document.getElementsByClassName('w2grid_embedded_check')[3].checked", "true");
    WebSquare.wUnit.addCommand("assert", "document.getElementsByClassName('w2grid_embedded_check')[5].checked", "true");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('G_gridView1___checkbox_col3_2').checked", "true");
    //Test step 9. label 이 출력된 Radio 에 라벨부분을 클릭한다. (임의로 몇번 더 선택)
    //9. Click on the label section of the radio with label. (Arbitrarily selected several more times)
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_1_2').childNodes[0].click()");
    //Verify step 9. 해당 Radio 가 선택된다.
    //9. The corresponding radio is selected.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('G_gridView1___radio_col2_1').checked", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 30-Jan-2018
    //end	
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
